import { quadtree } from "d3-quadtree";
import type { Feature, MultiLineString } from "geojson";
import { feature } from "topojson-client";
import type { Topo } from "./geo.js";
import type { ProjectedPoint } from "./teeth.js";

/**
 * USGS Quaternary faults as served by `GET /api/geo/wc-qfaults`: one feature
 * per fault section and style class, generated by the server's qfaults CLI.
 */

/** Age of last movement, after the USGS legend; `other` covers unspecified ages and Class B. */
export type AgeCode = "historic" | "latest" | "late" | "mid" | "undiff" | "other";
/** Mapping certainty: well constrained, moderately constrained, inferred. */
export type Cert = "well" | "mod" | "inf";

export interface FaultProps {
  id: string;
  name: string;
  section: string | null;
  age: AgeCode;
  cert: Cert;
  rate: string | null;
  sense: string | null;
  dip: string | null;
}

export type FaultFeature = Feature<MultiLineString, FaultProps>;

export interface FaultAge {
  label: string;
  /** A CSS colour expression; the variables carry light and dark values. */
  color: string;
}

export const FAULT_AGES: Record<AgeCode, FaultAge> = {
  historic: { label: "Historic (<150 yr)", color: "var(--qf-hist)" },
  latest: { label: "Latest Quaternary (<15 ka)", color: "var(--qf-latest)" },
  late: { label: "Late Quaternary (<130 ka)", color: "var(--qf-late)" },
  mid: { label: "Middle–late Quaternary (<750 ka)", color: "var(--qf-mid)" },
  undiff: { label: "Quaternary (<1.6 Ma)", color: "var(--qf-undiff)" },
  other: { label: "Age unspecified or Class B", color: "var(--qf-other)" },
};

export const FAULT_CERTS: Record<Cert, { label: string; dash: string | null }> = {
  well: { label: "well constrained", dash: null },
  mod: { label: "moderately constrained", dash: "5 3" },
  inf: { label: "inferred", dash: "1.5 3" },
};

/** Stroke width in screen pixels. */
export const FAULT_WIDTH = 1.2;

const isAge = (v: unknown): v is AgeCode =>
  typeof v === "string" && Object.keys(FAULT_AGES).includes(v);
const isCert = (v: unknown): v is Cert =>
  typeof v === "string" && Object.keys(FAULT_CERTS).includes(v);
const str = (v: unknown): string | null => (typeof v === "string" && v !== "" ? v : null);

/** Normalises a geometry's property bag; the file is generated, but it is still foreign JSON. */
export function faultProps(p: Record<string, unknown>): FaultProps {
  return {
    id: str(p.id) ?? "?",
    name: str(p.name) ?? "Unnamed fault",
    section: str(p.section),
    age: isAge(p.age) ? p.age : "other",
    cert: isCert(p.cert) ? p.cert : "well",
    rate: str(p.rate),
    sense: str(p.sense),
    dip: str(p.dip),
  };
}

/** The features of the `faults` object, lines promoted to multi-lines; empty when the object is missing. */
export function faultFeatures(topo: Topo): FaultFeature[] {
  const object = topo.objects.faults;
  if (object === undefined) return [];
  const decoded = feature(topo, object);
  const list = decoded.type === "FeatureCollection" ? decoded.features : [decoded];
  const out: FaultFeature[] = [];
  for (const f of list) {
    const g = f.geometry;
    const coordinates =
      g.type === "MultiLineString"
        ? g.coordinates
        : g.type === "LineString"
          ? [g.coordinates]
          : null;
    if (coordinates === null) continue;
    out.push({
      type: "Feature",
      properties: faultProps(f.properties),
      geometry: { type: "MultiLineString", coordinates },
    });
  }
  return out;
}

/** "Hayward fault zone, Southern Hayward section · Historic (<150 yr) · Between 1.0 and 5.0 mm/yr · Right lateral · Dip vertical". */
export function faultTitle(p: FaultProps): string {
  const where = p.section === null ? p.name : `${p.name}, ${p.section}`;
  const certNote = p.cert === "well" ? "" : `, ${FAULT_CERTS[p.cert].label}`;
  const age = `${FAULT_AGES[p.age].label}${certNote}`;
  const dip = p.dip === null ? null : `Dip ${p.dip === "Vertical" ? "vertical" : p.dip}`;
  return [where, age, p.rate, p.sense, dip].filter((s): s is string => s !== null).join(" · ");
}

export interface FaultHit {
  index: number;
  feature: FaultFeature;
}

export interface FaultIndex {
  /** The feature with a vertex within `radius` of (x, y) in projected units, nearest first. */
  nearest(x: number, y: number, radius: number): FaultHit | null;
}

type IndexedPoint = [number, number, FaultHit];

/**
 * Longest run, in projected (viewBox) units, between indexed points. Longer
 * segments get intermediate points, so a pointer anywhere on a trace is
 * within the hit radius of one even at the map's maximum zoom.
 */
export const INDEX_GAP = 0.25;

/**
 * A spatial index of the projected vertices, densified along long segments.
 * The nearest indexed point stands in for the nearest segment, and the map
 * needs no per-feature hit paths.
 */
export function faultIndex(
  features: FaultFeature[],
  project: (c: [number, number]) => ProjectedPoint,
  maxGap = INDEX_GAP,
): FaultIndex {
  const points: IndexedPoint[] = [];
  features.forEach((feature, index) => {
    const hit: FaultHit = { index, feature };
    for (const line of feature.geometry.coordinates) {
      let prev: [number, number] | null = null;
      for (const [lon, lat] of line) {
        if (lon === undefined || lat === undefined) continue;
        const q = project([lon, lat]);
        if (q === null) continue;
        if (prev !== null) {
          const steps = Math.ceil(Math.hypot(q[0] - prev[0], q[1] - prev[1]) / maxGap);
          for (let s = 1; s < steps; s++) {
            const t = s / steps;
            points.push([prev[0] + (q[0] - prev[0]) * t, prev[1] + (q[1] - prev[1]) * t, hit]);
          }
        }
        points.push([q[0], q[1], hit]);
        prev = q;
      }
    }
  });
  const tree = quadtree<IndexedPoint>()
    .x((d) => d[0])
    .y((d) => d[1])
    .addAll(points);
  return {
    nearest(x, y, radius) {
      const found = tree.find(x, y, radius);
      return found === undefined ? null : found[2];
    },
  };
}
